// Topic looks like ebusd/<device>/<name>
const parts = msg.topic.split('/');
if (parts.length !== 3) return null;
const device = parts[1];
const name = parts[2];

// Only keep readings we asked for
const wanted = flow.get('ebusd_wanted') || [];
if (!wanted.includes(`${device}/${name}`)) return null;

const p = msg.payload;
if (!p || typeof p !== 'object') return null;

let value;
if (name === 'Currenterror') {
    // Up to five codes; '-' means none. Keep the first real code, or 0.
    const codes = Object.values(p)
        .map(f => f && f.value)
        .filter(v => typeof v === 'number' && v > 0);
    value = codes.length ? codes[0] : 0;
} else {
    // The number is the 'value' inside the first field
    const first = Object.values(p)[0];
    value = first && first.value;
}
if (typeof value !== 'number') return null;

msg.topic = `${device}_${name}`;   // e.g. hmux0_BuildingCircuitFlow
msg.payload = value;
return msg;

// Store each reading with the time it arrived
const latest = flow.get('latest') || {};
latest[msg.topic] = { value: msg.payload, at: Date.now() };
flow.set('latest', latest);
return null;

// Write every reading heard from in the last 10 minutes
const latest = flow.get('latest') || {};
const cutoff = Date.now() - 10 * 60 * 1000;
const names = Object.keys(latest).filter(n => latest[n].at >= cutoff);
if (names.length === 0) return null;

msg.params = [names, names.map(n => latest[n].value)];
return msg;
